    """Draw expanding nested square frames around the 3 seed."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if not seeds:
        return out
    cy, cx = seeds[0]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and grid[r][c] != 2:
            out[r][c] = 3

    # Each frame is two cells farther out than the preceding one.
    radius = 2
    while (cy - radius < h and cy + radius >= 0 and
           cx - radius < w and cx + radius >= 0):
        t, b = cy - radius, cy + radius
        l, rr = cx - radius, cx + radius
        # Horizontal and vertical sides, clipped to the canvas.
        for c in range(l, rr + 1):
            paint(t, c)
            paint(b, c)
        for r in range(t, b + 1):
            paint(r, l)
            paint(r, rr)

        if radius == 2:
            # The inner frame has a one-cell break just left of its top midpoint.
            if 0 <= t < h and 0 <= cx - 1 < w and grid[t][cx - 1] != 2:
                out[t][cx - 1] = 0
        elif cy % 2 == 1:
            # The larger odd-row frame winds in from the upper-left corner.
            for c in (l, l + 1):
                if 0 <= t < h and 0 <= c < w and grid[t][c] != 2:
                    out[t][c] = 0
            for r in range(t, cy):
                if 0 <= r < h and 0 <= l < w and grid[r][l] != 2:
                    out[r][l] = 0
        else:
            # On the alternate orientation, leave the characteristic top-edge gap.
            gap_c = cx - (radius - 1)
            if 0 <= t < h and 0 <= gap_c < w and grid[t][gap_c] != 2:
                out[t][gap_c] = 0
        radius += 2
    return out

